{% block scripts %}
<script>
function previewFile(input, imgId) {
    const file = input.files[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = e => document.getElementById(imgId).src = e.target.result;
    reader.readAsDataURL(file);
}
function syncColor(textInput, pickerId, previewId) {
    const val = textInput.value;
    if (/^#[0-9a-fA-F]{6}$/.test(val)) {
        document.getElementById(pickerId).value = val;
        document.getElementById(previewId).style.background = val;
    }
}
function syncColorPicker(picker, textId, previewId) {
    document.getElementById(textId).value = picker.value;
    document.getElementById(previewId).style.background = picker.value;
}
function setColor(color, textId, pickerId, previewId) {
    document.getElementById(textId).value = color;
    document.getElementById(pickerId).value = color;
    document.getElementById(previewId).style.background = color;
    document.querySelectorAll('.color-swatch').forEach(s => s.classList.remove('active'));
    event.target.classList.add('active');
}
</script>
{% endblock %}

